import copy


def merge_config(defaults, overrides):
    """Recursively merge config dictionaries.

    When both the defaults and overrides values for a key are dicts,
    they are merged recursively. Otherwise the override value wins,
    including for lists and None. The returned mapping shares no
    state with either input: mutating a nested list or dict in the
    result never changes the originals.
    """
    result = {}
    for key in set(defaults) | set(overrides):
        in_default = key in defaults
        in_override = key in overrides
        default_val = defaults.get(key)
        override_val = overrides.get(key)

        if in_default and in_override:
            if isinstance(default_val, dict) and isinstance(override_val, dict):
                result[key] = merge_config(default_val, override_val)
            else:
                result[key] = copy.deepcopy(override_val)
        elif in_default:
            result[key] = copy.deepcopy(default_val)
        else:
            result[key] = copy.deepcopy(override_val)

    return result

