def merge_config(defaults, overrides):
    """Recursively merge overrides into defaults; return an independent result.

    Both inputs are never mutated. When a key holds dicts on both sides the
    dicts are merged recursively; any other combination (lists, None,
    scalars, mismatched types) is replaced by the overrides value. The
    returned structure is deep-copied, so mutating nested containers in the
    result cannot affect either input.
    """
    result = _deep_copy(defaults)
    for key, value in overrides.items():
        current = result.get(key)
        if isinstance(current, dict) and isinstance(value, dict):
            result[key] = merge_config(current, value)
        else:
            result[key] = _deep_copy(value)
    return result


def _deep_copy(value):
    if isinstance(value, dict):
        return {k: _deep_copy(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_deep_copy(v) for v in value]
    if isinstance(value, set):
        return {_deep_copy(v) for v in value}
    if isinstance(value, tuple):
        return tuple(_deep_copy(v) for v in value)
    return value

